import {loadPredictions,predictionWeaknesses} from './workshop-prediction-history.mjs';
import {guidedResultScore} from './workshop-repair-guided-history.mjs';
import {caseInfo} from './workshop-content.mjs';
import {alternate} from './workshop-challenges.mjs';
export function mountPredictionHistory({language,hidden,available,launch}){
 const root=document.createElement('section');root.id='guidedPredictionHistory';root.className='challenge-panel';document.querySelector('main').append(root);
 const t=(es,en)=>language()==='es'?es:en,name=(kind,id)=>(id==='primary'?caseInfo[kind].fix:alternate[kind].fix)[language()];
 function render(){root.hidden=hidden();if(root.hidden)return;root.replaceChildren();const add=(tag,text,parent=root)=>{const n=document.createElement(tag);n.textContent=text;parent.append(n);return n;};add('h2',t('Tus resultados de predicción guiada','Your guided prediction results'));let rows;try{rows=loadPredictions(localStorage);}catch{add('p',t('No se pudo leer el historial. Recarga para reintentar.','Could not read history. Reload to retry.'));return;}
 add('p',t('Prácticas de predicción identificadas desde esta actualización, dentro de las últimas 100 prácticas guiadas guardadas en este navegador. Las anteriores siguen en el historial general. Las decisiones y pistas se guardan al responder; los resultados se incorporan al terminar la práctica. Las notas de examen no cambian.','Prediction practices identified since this update, within the latest 100 guided practices saved in this browser. Older results remain in the general history. Decisions and hints save as you answer; completed results appear when you finish practice. Exam scores stay unchanged.'));
 if(!rows.length){add('p',t('Abre un examen completado y elige «Predecir la siguiente reparación» para empezar.','Open a completed exam and choose “Predict the next repair” to begin.'));return;}
 add('p',rows.length+t(' prácticas completadas · primera nota ',' completed practices · first score ')+guidedResultScore(rows[0])+'/100 · '+t('última nota ','latest score ')+guidedResultScore(rows.at(-1))+'/100');
 add('h3',t('Decisiones que más te cuestan','Your most difficult decisions'));add('p',t('Ordenadas por errores y luego por pistas. Compara también el total de elecciones. Los repasos conservan el fallo del caso donde te equivocaste para practicar cuándo actuar y cuándo evitar una reparación.','Ranked by mistakes, then hints. Also compare total choices. Reviews preserve the fault from the case you struggled with so you practise when to act and when to avoid a repair.'));
 for(const g of predictionWeaknesses(rows)){const card=add('article','');card.className='repair-progress-card';add('h4',name(g.kind,g.id),card);add('p',g.wrong+'/'+g.total+t(' elecciones innecesarias · ',' unnecessary choices · ')+g.repeated+t(' repetidas · ',' repeats · ')+g.unrelated+t(' sin esa causa presente · ',' with that cause absent · ')+g.hints+t(' pistas',' hints'),card);const b=add('button',g.wrong?t('Practicar esta dificultad en 3D','Practise this difficulty in 3D'):t('Reforzar esta decisión en 3D','Reinforce this decision in 3D'),card);b.dataset.predictionReview=g.key;b.disabled=!available();b.onclick=()=>launch(g);}
 if(!available())add('p',t('Abre un examen completado para entrar a los bancos 3D.','Open a completed exam to use the 3D benches.'));
 const details=add('details','');add('summary',t('Ver puntuaciones y decisiones','View scores and decisions'),details);
 for(const g of [...rows].reverse()){const card=add('article','',details);add('h4',new Date(g.finished).toLocaleString(language(),{timeZone:'America/Bogota'})+' · '+caseInfo[g.user.kind].title[language()]+' · '+guidedResultScore(g)+'/100',card);add('p',(g.source==='review'?t('Repaso personalizado','Personalized review'):t('Predicción inicial','Initial prediction'))+' · '+g.hints+t(' pistas',' hints'),card);const ol=add('ol','',card);for(const r of g.rounds)add('li',name(g.user.kind,r.id)+' · '+(r.useful?t('Útil','Useful'):t('Innecesaria','Unnecessary'))+(r.hint?t(' · con pista',' · with hint'):''),ol);}
 }
 return {render};
}
